# tests/ee/test_ripple_prompt_catalog_in_manifest.py — the chat prompt's widget
# vocabulary matches the Ripple manifest, the chat and Paw Bar rules stay apart,
# and the chat card quality log line.
#
# The chat prompt's widget block is generated by the Paw Bar generators
# (widget_relevance.core_lines and index_lines, concierge_runtime.ripple_rules for
# the chat profile) from the vendored manifest at
# src/pocketpaw/ripple/manifest.json. Guards both directions: a widget
# the chat prompt names that the manifest lacks renders as nothing, and a manifest
# widget the chat profile allows but the prompt never names is one the chat agent
# never learns exists. Paw Bar's rules and cards paragraph are pinned by hash, so
# making the rules profile-aware cannot move them (a manifest refresh does: re-pin).

from __future__ import annotations

import copy
import json
import logging
import re
from pathlib import Path
from unittest.mock import AsyncMock, patch

import pytest

_MANIFEST = (
    Path(__file__).resolve().parents[2] / "src" / "pocketpaw" / "ripple" / "manifest.json"
)


def _manifest() -> dict:
    return json.loads(_MANIFEST.read_text(encoding="utf-8"))


def _manifest_types() -> set[str]:
    return {w["type"] for w in _manifest()["widgets"]}


def _catalog_names(block: str) -> set[str]:
    """Widget names from a `category  a, b,` block (the atlas catalog format)."""
    names: set[str] = set()
    category = ""
    for line in block.splitlines():
        match = re.match(r"^([a-z][a-z-]*)\s{2,}(\S.*)$", line)
        if match:
            category, rest = match.group(1), match.group(2)
        elif line.startswith(" ") and category and "→" not in line:
            rest = line.strip()
        else:
            category = "" if not line.startswith(" ") else category
            continue
        if category != "control":
            names |= {t.strip() for t in rest.split(",") if t.strip()}
    return names


def _intent_targets(block: str) -> set[str]:
    targets = set()
    for line in block.splitlines():
        if "→" not in line:
            continue
        rhs = line.split("→", 1)[1].split()
        token = rhs[0].strip("`") if rhs else ""
        if re.fullmatch(r"[a-z][a-z0-9-]*", token):
            targets.add(token)
    return targets


def _chat_prompt() -> str:
    from pocketpaw_ee.cloud.chat.agent_service import chat_ripple_prompt

    return chat_ripple_prompt()


def _prompt_widgets() -> set[str]:
    """Widget names on the chat prompt's generated lines: '- name {props}: ...'
    for the listed widgets, '- category: a, b' for the index."""
    from pocketpaw_ee.paw_bar import widget_relevance

    prompt = _chat_prompt()
    names: set[str] = set()
    for line in widget_relevance.core_lines():
        assert line in prompt
        names.add(line[2:].split(" ", 1)[0].rstrip(":"))
    for line in widget_relevance.index_lines():
        assert line in prompt
        names |= {t.strip() for t in line.split(":", 1)[1].split(",")}
    return names


def test_shared_catalog_parse_matches_atlas():
    """The parser here reads WIDGET_CATALOG the way atlas does."""
    from pocketpaw.atlas.compile import _parse_widget_catalog
    from pocketpaw.ripple._design import WIDGET_CATALOG

    assert _catalog_names(WIDGET_CATALOG) == set(_parse_widget_catalog())


def test_every_prompt_widget_exists_in_the_manifest():
    unknown = sorted(_prompt_widgets() - _manifest_types())
    assert not unknown, f"the chat prompt names widgets the manifest lacks: {unknown}"


def test_every_chat_profile_widget_is_in_the_prompt():
    from pocketpaw_ee.paw_bar.chat_profile import CHAT_PROFILE

    missing = sorted(CHAT_PROFILE.widget_types - _prompt_widgets())
    assert not missing, f"widgets the chat agent is never told about: {missing}"


def test_chat_rules_name_chat_send_and_no_store_actions():
    p = _chat_prompt()
    assert "emit of chat.send" in p
    assert '"target":"chat.send"' in p
    for paw_bar_only in (
        "emit of add_to_cart",
        '"target":"ask"',
        "store-menu",
        "on_checkout",
        "pawbar-card",
        "Flow cards:",
    ):
        assert paw_bar_only not in p, paw_bar_only


def test_paw_bar_rules_and_cards_paragraph_are_unchanged():
    import hashlib

    from pocketpaw_ee.paw_bar import concierge_runtime as c
    from pocketpaw_ee.paw_bar.card_spec import PAWBAR_PROFILE, RIPPLE_PROFILE

    def h(text: str) -> str:
        return hashlib.sha256(text.encode()).hexdigest()

    assert c.ripple_rules(RIPPLE_PROFILE) is c._RIPPLE_RULES
    assert c.ripple_rules(PAWBAR_PROFILE) is c._RIPPLE_RULES
    assert h("\n".join(c._RIPPLE_RULES)) == (
        "d47ac0392c5e3ccc48319fc0fa9506f62e4a49286db227809fab4eaa241393d4"
    )
    pins = {
        "": "b465033c37135bcf96bda65b45770bc0c5248e6e83c2a7b9f0547c2cf02a9665",
        "plan a 3 day trip to Lisbon": (
            "8eda9ca5a344e9535a9cf75942a209898213e7e5ac29a54b4748cd01a8803195"
        ),
        "split the bill between 4 friends": (
            "24eeb1dcfb32ad3670bbf81ca8f315a499c457c380232d270a259d784703ac3f"
        ),
    }
    for message, pin in pins.items():
        assert h(c._cards_paragraph([], profile=RIPPLE_PROFILE, message=message)) == pin


def test_inline_prompt_names_only_handled_emit_channels():
    p = _chat_prompt()
    for dropped in ("chat.suggest", "tool.invoke", "nav.open"):
        assert dropped not in p, f"{dropped} is dropped by the chat host"
    assert "ONE typed widget is the answer most of the time" not in p
    assert "Expressions: one brace pair holds the whole expression" in p
    assert "25 to 90 nodes" in p
    assert '"each" takes items at node level, never inside props' in p


# ---------------------------------------------------------------------------
# log_chat_spec_quality — log-only, never blocks or changes the card
# ---------------------------------------------------------------------------

_SPEC = {
    "version": "1.0",
    "ui": {
        "type": "flex",
        "props": {"direction": "column"},
        "children": [
            {"type": "stat", "props": {"label": "Each pays", "valu": 3}},
            # `description` is a known timeline item alias (-> `detail`): the
            # log-only check must report it without rewriting the card.
            {
                "type": "timeline",
                "props": {"events": [{"date": "Jan", "title": "A", "description": "x"}]},
            },
        ],
    },
}


@pytest.mark.asyncio
async def test_chat_spec_quality_logs_counts_without_changing_the_spec(caplog):
    from pocketpaw_ee.cloud import ripple_validator

    spec = copy.deepcopy(_SPEC)
    with (
        patch.object(ripple_validator, "get_manifest", AsyncMock(return_value=_manifest())),
        caplog.at_level(logging.INFO, logger=ripple_validator.log.name),
    ):
        await ripple_validator.log_chat_spec_quality(spec, run_id="run-1")

    assert spec == _SPEC
    records = [r for r in caplog.records if r.getMessage() == "ripple_chat_spec.quality"]
    assert len(records) == 1
    rec = records[0]
    assert rec.run_id == "run-1"
    assert rec.node_count == 3
    assert rec.widget_types == ["flex", "stat", "timeline"]
    assert "stat.valu" in rec.unknown_props
    assert "stat.value" in rec.missing_required
    assert rec.missing_required_count >= 1
    assert rec.item_alias_count == 1


@pytest.mark.asyncio
async def test_chat_spec_quality_skips_quietly_without_a_manifest(caplog):
    from pocketpaw_ee.cloud import ripple_validator

    with (
        patch.object(ripple_validator, "get_manifest", AsyncMock(return_value=None)),
        caplog.at_level(logging.INFO, logger=ripple_validator.log.name),
    ):
        await ripple_validator.log_chat_spec_quality(copy.deepcopy(_SPEC), run_id="run-2")
    assert not [r for r in caplog.records if r.getMessage() == "ripple_chat_spec.quality"]


@pytest.mark.asyncio
async def test_chat_spec_quality_never_raises():
    from pocketpaw_ee.cloud import ripple_validator

    with patch.object(ripple_validator, "get_manifest", AsyncMock(side_effect=RuntimeError("x"))):
        await ripple_validator.log_chat_spec_quality(copy.deepcopy(_SPEC), run_id="run-3")
